nonisolated enum MobileBrowserScreencastEventWire: Decodable, Sendable {
    case ready(MobileBrowserReadyWire)
    case end(String)
    case dialog(type: String, message: String)
    case dialogClosed
    case error(String)

    private enum EventType: String, Decodable {
        case ready
        case end
        case dialog
        case dialogClosed
        case error
    }

    private enum CodingKeys: String, CodingKey {
        case type
        case subscriptionId
        case dialogType
        case message
    }

    init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        switch try container.decode(EventType.self, forKey: .type) {
        case .ready:
            self = .ready(try MobileBrowserReadyWire(from: decoder))
        case .end:
            self = .end(try container.decode(String.self, forKey: .subscriptionId))
        case .dialog:
            self = .dialog(
                type: try container.decode(String.self, forKey: .dialogType),
                message: try container.decode(String.self, forKey: .message)
            )
        case .dialogClosed:
            self = .dialogClosed
        case .error:
            self = .error(try container.decode(String.self, forKey: .message))
        }
    }
}

